import React, { useEffect, useRef } from 'react';
import { TextInputProps, View } from 'react-native';
import { BottomSheetManager, BottomSheet, BottomSheetRef } from '@core/ui';
import ContentInput from '../contentInput';
import { ValidationResult } from '@src/utils/validator';
import { IS_IOS } from '@core/service';

interface BottomSheetInputProps {
    label: string;
    onSubmit: (value: string) => void;
    labelSubmit: string;
    textInputProps: TextInputProps;
    show: boolean;
    title: string;
    onClose?: () => void;
    format?: string;
    inputType?: string;
    validate?: (value: string) => ValidationResult;
}

const BottomSheetInput = (props: BottomSheetInputProps) => {
    const { label, onSubmit, textInputProps, title, show, onClose, format, inputType, validate } = props;
    const { value, placeholder, maxLength } = textInputProps;
    const bsRef = useRef<BottomSheetRef>(null);

    const handlePressSubmit = (value: string) => {
        onSubmit?.(value?.trim?.());
        bsRef.current?.close();
    };
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} adjustKeyboard={false} safeAreaBottomOffset={IS_IOS ? 370 : undefined} snapPoints={['75%']} >
                    <ContentInput value={value ?? ''} onSubmit={handlePressSubmit} label={label} placeholder={placeholder} format={format} inputType={inputType} validate={validate} textInputProps={textInputProps} />
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);

    return (
        <View></View>
    );
};

export default BottomSheetInput;
