import React, { useEffect, useRef, useState } from 'react';
import { TextInput, TextInputChangeEventData, TextInputProps, TouchableOpacity, View } from 'react-native';
import { useTheme, Text, GradientContainer, MaterialTextInput, BottomSheetManager, BottomSheet, BottomSheetRef, FormInput } from '@core/ui';
import useStyles from './styles';
import GorhomBottomSheet from '@gorhom/bottom-sheet';
import ContentInput from '../contentInput';
import ContentBranch from '../contentBranch';
import { IBranch } from '@src/domain/entities/common/branch';
import { ScrollView } from 'react-native-gesture-handler';

interface BottomSheetInputProps {
    label?: string;
    onSubmit: (value: IBranch) => void;
    labelSubmit?: string;
    show: boolean;
    title: string;
    onClose?: () => void;
    format?: string;
    data?: any;
    selected?: string;
    onSelected?: (data: any) => void;
}

const BottomSheetBranch = (props: BottomSheetInputProps) => {
    const { theme } = useTheme();
    const styles = useStyles();
    const { label, onSubmit, labelSubmit, title, show, onClose, data, selected, onSelected = () => {} } = props;
    // const { value, onChangeText, placeholder } = textInputProps;
    const bsRef = useRef<BottomSheetRef>(null);

    // const renderContentModal = () => {
    //     return (
    //         <ModalInput
    //             label={label}
    //             onSubmit={handlePressSubmit}
    //             labelSubmit={labelSubmit}
    //             textInputProps={{ ...textInputProps, value: phoneNumber, onChangeText: (text: string) => { setPhoneNumber(text); console.log('\x1b[31m valueee', text); } }}
    //         />
    //     );
    // };
    const handleSelectItem = (value: IBranch) => {
        onSubmit?.(value);
        bsRef.current?.close();
    };
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} enableContentPanningGesture={false} snapPoints={['80%']}>
                    <ContentBranch data={data} selected={selected || ''} onSelect={handleSelectItem} />
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return <View></View>;
};

export default BottomSheetBranch;
