import { TYPES } from '@src/di/types/types';
import { inject, injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import type { IAddressRepository } from '@src/domain/interfaces/address/address';
import { GetProvincePayload } from './get_province_payload';
import { GetDistrictPayload } from './get_district_payload';
import { GetWardPayload } from './get_ward_payload';
@injectable()
export class GetAddressHandler {
    private readonly _addressRepository: IAddressRepository;
    constructor(@inject(TYPES.IAddressRepository) addressRepository: IAddressRepository) {
        this._addressRepository = addressRepository;
    }
    handle_get_province(query: Query<GetProvincePayload>) {
        return this._addressRepository.getProvinceList(query);
    }
    handle_get_district(query: Query<GetDistrictPayload>) {
        return this._addressRepository.getDistrictList(query);
    }
    handle_get_ward(query: Query<GetWardPayload>) {
        return this._addressRepository.getWardList(query);
    }
}